// today-dashboard — вкладка «Сегодня». Экран решений, а не сводка новостей.
// Источники: Get Daily_Trends, Get Meals, Get Nutrient_Targets, Get Doctor_Notes,
//            Get Recommendations_Log, Get PhenoAge_Log, Get Action_Log.
// Порядок блоков: сверху то, на что влияешь прямо сейчас; хроника и лаборатория — внизу.
// Run Once for All Items.

function safeAll(name) { try { return $(name).all().map(i => i.json); } catch (e) { return []; } }
function num(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v).replace('%', '').replace(',', '.'));
  return isNaN(n) ? null : n;
}
function dkey(v) { return String(v == null ? '' : v).slice(0, 10); }
function d10(v) {
  const s = String(v == null ? '' : v).trim();
  let m = s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})/);
  if (m) return m[3] + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0');
  m = s.match(/^(\d{4})[.\/-](\d{1,2})[.\/-](\d{1,2})/);
  if (m) return m[1] + '-' + m[2].padStart(2, '0') + '-' + m[3].padStart(2, '0');
  return s.slice(0, 10);
}
function r1(x) { return x == null ? null : Math.round(x * 10) / 10; }
function mean(a) { const x = a.filter(v => v != null); return x.length ? x.reduce((s, v) => s + v, 0) / x.length : null; }

const daily   = safeAll('Get Daily_Trends');
const meals   = safeAll('Get Meals');
const targets = safeAll('Get Nutrient_Targets');
const notes   = safeAll('Get Doctor_Notes');
const recs    = safeAll('Get Recommendations_Log');
const pheno   = safeAll('Get PhenoAge_Log');
const acts    = safeAll('Get Action_Log');       // может не существовать — нода с onError:continue
const pstate  = safeAll('Get Patient_State');    // карта хронических состояний (Этап 1)
const profRows= safeAll('Get User_Profile');
const profile = profRows[0] || {};

// ---------- время ----------
const nowVl   = new Date(Date.now() + 10 * 3600 * 1000);          // Владивосток = UTC+10
const todayISO = nowVl.toISOString().slice(0, 10);
const nowMin  = nowVl.getUTCHours() * 60 + nowVl.getUTCMinutes();
function hhmm(min) {
  const m = ((min % 1440) + 1440) % 1440;
  return String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
}

const rows = daily.filter(r => r['Дата']).sort((a, b) => dkey(a['Дата']).localeCompare(dkey(b['Дата'])));
// последняя строка НЕ ПОЗЖЕ сегодня — строки с будущей датой (заглушки под новые колонки,
// приходящие данные) не должны становиться источником «Решения дня».
const pastRows = rows.filter(r => dkey(r['Дата']) <= todayISO);
const last = pastRows[pastRows.length - 1] || rows[rows.length - 1] || {};
const lastDate = dkey(last['Дата']) || todayISO;

// =====================================================================
// 1. РЕШЕНИЕ ДНЯ — нагрузка или восстановление
// =====================================================================
// Базовая линия ВСР за 30 дней (как в детекторе аномалий: окно ДО текущего дня)
function baseline(col, days) {
  const from = new Date(new Date(lastDate + 'T00:00:00Z').getTime() - days * 86400000).toISOString().slice(0, 10);
  const v = rows.filter(r => dkey(r['Дата']) >= from && dkey(r['Дата']) < lastDate).map(r => num(r[col]));
  return mean(v);
}
const bb      = num(last['Восстановление_BodyBattery']);
const hrv     = num(last['ВСР_ночная']);
const hrvBase = baseline('ВСР_ночная', 30);
const hrvDelta = (hrv != null && hrvBase != null) ? hrv - hrvBase : null;

// Нагрузка: ACWR берём у Garmin — он считает его сам (dailyAcuteChronicWorkloadRatio +
// acwrStatus LOW/OPTIMAL/HIGH, поля ACWR_Garmin / ACWR_Status, Этап 5). В старых строках
// Daily_Trends этих полей ещё нет → откат на самодельный расчёт (7д/28д по калориям тренировок).
function loadMean(days) {
  const from = new Date(new Date(lastDate + 'T00:00:00Z').getTime() - days * 86400000).toISOString().slice(0, 10);
  return mean(rows.filter(r => dkey(r['Дата']) > from).map(r => num(r['Тренировка_Ккал']) || 0));
}
const acwrGarmin  = num(last['ACWR_Garmin']);
const acwrStatusG = String(last['ACWR_Status'] || '').trim().toUpperCase() || null;
let acwr, acwrSource;
if (acwrGarmin != null) {
  acwr = acwrGarmin;
  acwrSource = 'garmin';
} else {
  const acute = loadMean(7), chronic = loadMean(28);
  acwr = (acute != null && chronic) ? Math.round((acute / chronic) * 100) / 100 : null;
  acwrSource = acwr != null ? 'self' : null;
}
// «перегруз»: Garmin говорит HIGH, либо (на самодельном ACWR) отношение > 1.5
const loadHigh = acwrStatusG ? acwrStatusG === 'HIGH' : (acwr != null && acwr > 1.5);

// ---------------------------------------------------------------------
// ГЕЙТ БЕЗОПАСНОСТИ (Этап 1). Fail-safe: нет данных о снятии → ограничение действует.
// Авторитетный источник — Patient_State; если пуст/недоступен — читаем профиль.
// Возвращает медицинский потолок нагрузки, который НЕЛЬЗЯ превысить,
// что бы ни показывали Body Battery / ВСР.
// Уровни: 0 отдых · 1 ходьба · 2 +плавание · 3 умеренная аэробика · 4 интенсив
// ---------------------------------------------------------------------
const HERNIA_RX = /грыж|радикулопат|протру[зи]|экструз|модик|modic|корешк/i;
function loadGate() {
  const active = pstate.filter(x =>
    String(x.Status || '').toLowerCase() === 'active' &&
    String(x.Contra_Load || '').trim());
  if (active.length) {
    const x = active.sort((a, b) => String(b.Confirmed_Date).localeCompare(String(a.Confirmed_Date)))[0];
    const swim = /плаван/i.test(x.Allowed || '');
    return {
      cap: swim ? 2 : 1, blocked: true, condition: x.Condition,
      contra: x.Contra_Load, allowed: x.Allowed || '', provokers: x.Provokers || '',
      review_due: x.Review_Due || null,
      source: (x.Source || 'карта пациента') + (x.Confirmed_Date ? ' от ' + x.Confirmed_Date : ''),
    };
  }
  const oda = String(profile['ОДА и неврология'] || profile['ОДА и неврология '] || '');
  const profHernia = HERNIA_RX.test(oda) && !/ремисси|снят|полн(ое|ая) восстановлен|разрешена нагрузка/i.test(oda);
  const profSwim = profHernia && /плаван|бассейн/i.test(oda);

  // A6 fail-safe (ревью Opus 5, 2026-09-09): Patient_State ЗАСИЖЕН строкой про грыжу
  // (_setup helper sheets, state_id=hernia_l5s1). 0 строк там = чтение НЕ ПРОШЛО (rate-limit),
  // а НЕ «ограничений нет». Это верно НЕЗАВИСИМО от того, прочитался ли профиль.
  if (pstate.length === 0) {
    return {
      cap: profSwim ? 2 : 1, blocked: true, degraded: true,
      condition: profHernia
        ? 'Грыжа/радикулопатия — Patient_State не прочитан, профиль подтверждает'
        : 'Карта пациента не прочитана (Patient_State пуст)',
      contra: 'осевая нагрузка, подъём тяжестей, скручивания, бег, прыжки, интервалы',
      allowed: 'ходьба' + (profSwim ? ', плавание' : ''),
      provokers: '', review_due: null,
      source: '⚠️ PATIENT_STATE НЕ ПРОЧИТАН' + (profHernia ? ' (профиль подтверждает грыжу)' : ''),
    };
  }

  // Patient_State прочитан, активных ограничений нет — но профиль страхует (belt-and-suspenders).
  if (profHernia) {
    return {
      cap: profSwim ? 2 : 1, blocked: true,
      condition: 'Грыжа/радикулопатия (из профиля; в Patient_State активных ограничений нет)',
      contra: 'осевая нагрузка, подъём тяжестей, скручивания, бег/прыжки/интенсив',
      allowed: 'ходьба' + (profSwim ? ', плавание' : ''),
      provokers: '', review_due: null,
      source: 'User_Profile (Patient_State без активных ограничений)',
    };
  }

  return { cap: 4, blocked: false, condition: null, contra: null, allowed: '', provokers: '', review_due: null, source: null };
}
const gate = loadGate();

const reasons = [];
if (bb != null) reasons.push({ label: 'Body Battery', value: bb, judgment: bb >= 70 ? 'good' : bb >= 40 ? 'neutral' : 'bad' });
if (hrvDelta != null) reasons.push({
  label: 'ВСР к базе', value: (hrvDelta > 0 ? '+' : '') + r1(hrvDelta) + ' мс',
  judgment: Math.abs(hrvDelta) < 6 ? 'neutral' : hrvDelta > 0 ? 'good' : 'bad',
});
if (acwr != null) reasons.push({
  label: acwrSource === 'garmin' ? 'ACWR (Garmin)' : 'Нагрузка 7д/28д',
  value: acwrStatusG ? `${acwr} · ${acwrStatusG}` : acwr,
  judgment: loadHigh ? 'bad' : (acwrStatusG === 'LOW' || acwr < 0.8) ? 'neutral' : 'good',
});

// физиологическая готовность (по восстановлению) -> потолок 1..4
let readiness = 0;
if (bb != null) {
  const hrvBad = hrvDelta != null && hrvDelta <= -6;
  readiness = (bb >= 70 && !hrvBad && !loadHigh) ? 4 : (bb >= 40 && !loadHigh) ? 3 : 1;
}
// Нет свежих данных Garmin (часы не синхронизировались / пропущен ночной прогон / строка-заглушка).
// Фаза 1.2: без данных о восстановлении — потолок «ходьба и плавание», не собираем вердикт из нулей.
const noGarminToday = bb == null && hrv == null && num(last['Чистый_сон_мин']) == null;

// финальный потолок — минимум из медицинского и физиологического
let finalCap;
if (noGarminToday) finalCap = Math.min(gate.blocked ? gate.cap : 2, 2);
else if (bb == null) finalCap = gate.blocked ? gate.cap : 0;
else finalCap = Math.min(gate.cap, readiness);
const CAP_LABEL = { 0: 'нет данных', 1: 'только ходьба', 2: 'ходьба и плавание', 3: 'умеренная аэробика', 4: 'можно интенсив' };
const verdict = CAP_LABEL[finalCap];

let verdictNote;
if (noGarminToday) {
  verdictNote = gate.blocked
    ? `Нет свежих данных Garmin + ${gate.condition}. Режим: ${verdict}, ничего сверх, пока часы не синхронизируются.`
    : 'Нет свежих данных Garmin (часы не синхронизировались?). Режим: ходьба и плавание, пока данные не появятся — вердикт по восстановлению не строим.';
} else if (bb == null && !gate.blocked) {
  verdictNote = 'Не хватает данных Garmin за сегодня — держись лёгкой активности.';
} else if (gate.blocked && gate.cap <= readiness) {
  // медицинское ограничение — главная причина
  verdictNote = `${gate.condition}: ${gate.contra}. По восстановлению запас ${readiness >= 4 ? 'полный' : readiness >= 3 ? 'средний' : 'низкий'}, но это не отменяет ограничение по спине.`;
} else if (finalCap >= 4) {
  verdictNote = 'Резерв восстановления есть, ВСР не просела, нагрузка не накоплена. Ограничений по здоровью нет.';
} else if (finalCap === 3) {
  verdictNote = (hrvDelta != null && hrvDelta <= -6)
    ? 'ВСР ниже твоей базы — аэробная работа без ударных интервалов.'
    : 'Резерв средний: аэробная работа без интенсива.';
} else {
  verdictNote = loadHigh
    ? 'Накоплена нагрузка — сегодня разгрузочный день.'
    : 'Низкий резерв восстановления — сегодня только лёгкая активность.';
}

const decision = {
  verdict, note: verdictNote, reasons,
  gate: {
    blocked: gate.blocked, condition: gate.condition, contra: gate.contra,
    allowed: gate.allowed, provokers: gate.provokers,
    review_due: gate.review_due, source: gate.source, degraded: !!gate.degraded,
  },
  readiness_cap: readiness, medical_cap: gate.cap, final_cap: finalCap,
  no_garmin_today: noGarminToday,
  acwr, acwr_status: acwrStatusG, acwr_source: acwrSource, load_high: loadHigh,
  garmin_device: last['Garmin_устройство'] || null,
  training_status: last['Training_Status'] || null,
  // старые поля — для совместимости с текущим фронтендом
  caution: gate.blocked ? `${gate.condition}. Разрешено: ${gate.allowed || 'ходьба'}` : null,
  limit: gate.blocked ? gate.contra : null,
};

// =====================================================================
// 2. ОКНА ДНЯ
// =====================================================================
// Целевой отбой: если советник дал действие со временем — берём его, иначе 23:30.
function parseActions(txt) {
  const m = String(txt || '').match(/<<<ACTIONS\s*([\s\S]*?)\s*ACTIONS>>>/);
  if (!m) return null;
  try { const o = JSON.parse(m[1].trim()); return (o && Array.isArray(o.actions)) ? o : null; } catch (e) { return null; }
}
const recSorted = recs.filter(r => r.Recommendation_Text && dkey(r.Date) <= todayISO)
  .sort((a, b) => dkey(b.Date).localeCompare(dkey(a.Date)));
const latestRec = recSorted[0] || null;
const latestParsed = latestRec ? parseActions(latestRec.Recommendation_Text) : null;
const latestActions = latestParsed ? latestParsed.actions : [];

let bedMin = 23 * 60 + 30;
for (const a of latestActions) {
  const m = String(a.title || '').match(/(\d{1,2})[:.](\d{2})/);
  if (m && /отбо|спат|лож|сон/i.test(a.title)) { bedMin = (+m[1]) * 60 + (+m[2]); break; }
}
const coffeeMin = bedMin - 8 * 60;   // кофеин: период полувыведения ~5–6 ч
const mealMin   = bedMin - 3 * 60;   // последняя еда за 3 ч до сна

// ВАЖНО: обратный отсчёт здесь НЕ считаем — это кэш, значение протухнет к моменту просмотра.
// Бэкенд отдаёт только целевое время, «сколько осталось» считает браузер при отрисовке.
function windowOf(key, label, targetMin, hint) {
  return { key, label, until: hhmm(targetMin), target_min: targetMin, hint };
}
const windows = [
  windowOf('coffee', 'Последний кофе', coffeeMin, 'за 8 ч до отбоя'),
  windowOf('meal', 'Последняя еда', mealMin, 'за 3 ч до отбоя'),
  windowOf('bed', 'Отбой', bedMin, latestActions.some(a => /отбо|спат/i.test(a.title || '')) ? 'из плана советника' : 'цель по умолчанию'),
];

// серии: сколько ночей подряд сон в целевой зоне 7–9 ч
const SLEEP_MIN_OK = 420, SLEEP_MAX_OK = 540;
let sleepStreak = 0;
for (let i = rows.length - 1; i >= 0; i--) {
  const v = num(rows[i]['Чистый_сон_мин']);
  if (v != null && v >= SLEEP_MIN_OK && v <= SLEEP_MAX_OK) sleepStreak++; else break;
}
const streaks = [];
if (sleepStreak > 0) streaks.push({ label: 'Сон в зоне 7–9 ч', count: sleepStreak, unit: 'ночей' });

// =====================================================================
// 3. БЮДЖЕТ ДНЯ — сколько ещё можно / сколько добрать
// =====================================================================
function parseTargetNum(v) {
  if (v == null) return null;
  const s = String(v).trim();
  if (/^не\s/i.test(s)) return null;
  const m = s.match(/-?\d+(?:[.,]\d+)?/);
  return m ? parseFloat(m[0].replace(',', '.')) : null;
}
const todayMeals = meals.filter(m => m.Date && dkey(m.Date) === todayISO);
function sumCol(col) {
  return todayMeals.reduce((s, m) => s + (num(m[col]) || 0), 0);
}
// что показываем в бюджете: лимиты, которые легко пробить, и цели, которые обычно недобираются
const BUDGET_KEYS = ['Насыщенные жиры', 'Добавленный сахар', 'Натрий', 'Кофеин', 'Клетчатка', 'Витамин D', 'Кальций'];
const budget = [];
for (const t of targets) {
  const name = t['Нутриент'];
  if (!BUDGET_KEYS.includes(name)) continue;
  const col = t['Колонка_в_Meals'];
  if (!col) continue;
  const isLimit = String(t['Категория'] || '').includes('Риск избытка');
  const rda = parseTargetNum(t['Норма_RDA_AI']);
  const ul  = parseTargetNum(t['Верхний_предел_UL']);
  const cap = isLimit ? ul : rda;
  if (!cap) continue;
  const consumed = Math.round(sumCol(col) * 100) / 100;
  const pct = Math.round((consumed / cap) * 100);
  budget.push({
    label: name, unit: t['Единица'] || '', kind: isLimit ? 'limit' : 'goal',
    consumed, cap, pct,
    remaining: Math.round((cap - consumed) * 100) / 100,
    status: isLimit ? (pct > 100 ? 'over' : pct >= 80 ? 'close' : 'ok')
                    : (pct >= 100 ? 'done' : pct >= 60 ? 'partial' : 'low'),
  });
}
budget.sort((a, b) => (a.kind === b.kind ? b.pct - a.pct : a.kind === 'limit' ? -1 : 1));

// протеин/калории за сегодня — из тех же Meals
const kcalToday = Math.round(sumCol('Calories'));
const protToday = Math.round(sumCol('Proteins'));

// =====================================================================
// 4. ПЛАН НЕДЕЛИ + отметки выполнения
// =====================================================================
// Без отметки «сделал» замер эффекта в «Что сработало» measures совпадение, а не эффект.
function actionId(issued, title) {
  return (issued || '') + '|' + String(title || '').slice(0, 60).replace(/\s+/g, ' ').trim();
}
const doneMap = {};
acts.forEach(a => {
  if (a.Action_ID) doneMap[String(a.Action_ID)] = String(a.Done || '').toLowerCase() === 'да'
    || String(a.Done || '').toLowerCase() === 'true' || a.Done === true;
});
const issued = latestRec ? dkey(latestRec.Date) : null;
// Блокировка гейтом — по ТИПУ действия из машинного блока советника (Фаза 1), не по regex.
// Fail-safe: нет type / other + нагрузочно звучит → тоже блок.
const LOAD_RX = /интенсив|интервал|hiit|бег|пробеж|прыж|присед|становая|штанг|турник|подтяг|отжим|планк|скручиван|макгил|ротац|наклон|подним|тяж(?:есть|ести|[её]л|\b)|спринт|силов|кроссфит|бадминтон|берпи|выпад|растяж|мобилити|йог|лфк|упражнен|качат|тренаж|скакалк|степ[- ]?аэроб|ударн|отягощ|гантел|гир(?:я|ю|ей)|планер/i;
const allowedLC = String(gate.allowed || '').toLowerCase();
const gAllowWalk = /ходьб|walk|прогул/.test(allowedLC);
const gAllowSwim = /плаван|бассейн|swim/.test(allowedLC);
function actionConflicts(a) {
  if (!gate.blocked) return false;
  const t = String(a.type || '').toLowerCase();
  if (t === 'load_high' || t === 'load_low') return true;
  if (t === 'walk') return !gAllowWalk;
  if (t === 'swim') return !gAllowSwim;
  // Opus 5: regex по ВСЕМ типам (не только other/unknown) — type-метку ставит та же LLM.
  if (LOAD_RX.test(String(a.title) + ' ' + String(a.why))) return true;
  if (gate.degraded && (!t || t === 'unknown')) return true;   // карта недоступна → режем сомнительное
  return false;
}
const plan = {
  date: issued,
  actions: latestActions.map(a => {
    const conflicts = actionConflicts(a);
    return {
      id: actionId(issued, a.title),
      title: a.title, why: a.why || '', expect: a.expect || '',
      priority: a.priority || 'средний', metric: a.metric || null, type: a.type || null,
      done: !!doneMap[actionId(issued, a.title)],
      blocked_by_gate: conflicts,
      gate_note: conflicts ? `Противоречит ограничению: ${gate.condition}. Разрешено только: ${gate.allowed || 'ходьба'}` : null,
    };
  }),
};

// =====================================================================
// 5. ДЛЯ ДОЛГОЛЕТИЯ — что из сегодняшнего реально двигает биовозраст
// =====================================================================
const phenoValid = pheno.filter(p => num(p.phenoage) != null && dkey(p.date))
  .sort((a, b) => dkey(b.date).localeCompare(dkey(a.date)));
const ph = phenoValid[0] || null;
const longevity = ph ? {
  phenoage: num(ph.phenoage), chrono_age: num(ph.chrono_age), delta: num(ph.delta),
  computed: dkey(ph.date),
  // Честно: PhenoAge считается по крови. Сон и стресс за один день туда не попадают —
  // попадает то, что системно меняет воспаление, обмен и картину крови.
  affects_today: [
    { what: 'Насыщенные жиры и сахар', how: 'через воспаление и липиды — попадает в СРБ и обмен', weight: 'да' },
    { what: 'Регулярная нагрузка', how: 'через обмен глюкозы и состав крови', weight: 'да' },
    { what: 'Сон и стресс за один день', how: 'на PhenoAge напрямую не влияют — это про самочувствие', weight: 'нет' },
  ],
} : null;

// =====================================================================
// 6. СПОКОЙНО — что проверено и в норме
// =====================================================================
const quiet = [];
const REF = { 'SpO2_ночь_среднее': [95, 100], 'Дыхание_ночь_среднее': [12, 20] };
for (const [col, [lo, hi]] of Object.entries(REF)) {
  const v = num(last[col]);
