const gAllowWalk = /ходьб|walk|прогул/.test(allowedLC);
const gAllowSwim = /плаван|бассейн|swim/.test(allowedLC);
function actionConflicts(a) {
  if (!gate.blocked) return false;
  const t = String(a.type || '').toLowerCase();
  if (t === 'load_high' || t === 'load_low') return true;
  if (t === 'walk') return !gAllowWalk;
  if (t === 'swim') return !gAllowSwim;
  // Opus 5: regex по ВСЕМ типам (не только other/unknown) — type-метку ставит та же LLM.
  if (LOAD_RX.test(String(a.title) + ' ' + String(a.why))) return true;
  if (gate.degraded && (!t || t === 'unknown')) return true;   // карта недоступна → режем сомнительное
  return false;
}
const plan = {
  date: issued,
  actions: latestActions.map(a => {
    const conflicts = actionConflicts(a);
    return {
      id: actionId(issued, a.title),
      title: a.title, why: a.why || '', expect: a.expect || '',
      priority: a.priority || 'средний', metric: a.metric || null, type: a.type || null,
      done: !!doneMap[actionId(issued, a.title)],
      blocked_by_gate: conflicts,
      gate_note: conflicts ? `Противоречит ограничению: ${gate.condition}. Разрешено только: ${gate.allowed || 'ходьба'}` : null,
    };
  }),
};

